const icon = 'data:image/png;base64,';

class OddMessage {
    constructor(runtime) {
        this.runtime = runtime;
        this.messageQueue = [];
        this.recording = [];
        this.logs = [];
        this.recordingDelay = 1000;
    }
    getInfo() {
        return {
            id: 'oddMessage',
            name: 'Odd Messages',
            menuIconURI: icon,
            blockIconURI: icon,
            color1: '#BE00FF',
            blocks: [
                {
                    opcode: 'emit',
                    blockType: 'command',
                    text: 'emit [a] [b]',
                    arguments: {
                        a: {
                            type: 'string',
                            defaultValue: 'message',
                        },
                        b: {
                            type: 'string',
                            defaultValue: 'data',
                        },
                    },
                },
                {
                    opcode: 'on',
                    blockType: 'hat',
                    text: 'on [a] set [b]',
                    arguments: {
                        a: {
                            type: 'string',
                            defaultValue: 'message',
                        },
                        b: {
                            type: 'string',
                            menu: 'variables',
                        },
                    },
                },
                '---',
                {
                    opcode: 'whenVarChange',
                    blockType: 'hat',
                    text: 'when [a] changes',
                    arguments: {
                        a: {
                            type: 'string',
                            menu: 'variables',
                        },
                    },
                },
                {
                    opcode: 'recordVar',
                    blockType: 'command',
                    text: 'record [a] in list [b]',
                    arguments: {
                        a: {
                            type: 'string',
                            menu: 'variables',
                        },
                        b: {
                            type: 'string',
                            menu: 'lists',
                        },
                    },
                },
                {
                    opcode: 'stopRecording',
                    blockType: 'command',
                    text: 'stop recording [a]',
                    arguments: {
                        a: {
                            type: 'string',
                            menu: 'variables',
                        },
                    },
                },
                {
                    opcode: 'setRecordingDelay',
                    blockType: 'command',
                    text: 'set recording delay to [a]',
                    arguments: {
                        a: {
                            type: 'number',
                            defaultValue: 1000,
                        },
                    },
                },
                '---',
                {
                    opcode: 'logToJSON',
                    blockType: 'reporter',
                    text: 'list logs',
                },
                {
                    opcode: 'log',
                    blockType: 'command',
                    text: 'log [a] as [b]',
                    arguments: {
                        a: {
                            type: 'string',
                            defaultValue: 'message',
                        },
                        b: {
                            type: 'string',
                            defaultValue: 'warn',
                        },
                    },
                },
                {
                    opcode: 'logClear',
                    blockType: 'command',
                    text: 'clear logs',
                },
                {
                    opcode: 'logToArray',
                    blockType: 'reporter',
                    text: '#[n] log as array',
                    arguments: {
                        n: {
                            type: 'number',
                            defaultValue: 0,
                        },
                    },
                },
            ],
            menus: {
                variables: {
                    acceptReporters: true,
                    items: '_getVariableMenu',
                },
                lists: {
                    acceptReporters: true,
                    items: '_getListMenu',
                },
            },
        }
    }
    _getVariableMenu() {
        const vars = this.runtime.getAllVarNamesOfType('')
        return vars.length == 0 ? [" "] : vars
    }
    _getListMenu() {
        const lists = this.runtime.getAllVarNamesOfType('list')
        return lists.length == 0 ? [" "] : lists
    }
    log({ a, b }) {
        this.logs.push({ log: a, type: b });
    }
    logClear() {
        this.logs = [];
    }
    logToArray({ n }) {
        let a = this.logs[n];
        if (a) {
            return JSON.stringify([a.log, a.type]);
        } else {
            return '[]';
        }
    }
    logToJSON() {
        return JSON.stringify(this.logs);
    }
    emit({ a, b }) {
        this.messageQueue.push([a, b]);
    }
    on({ a, b }) {
        if (this.messageQueue.length == 0) return false;
        if (this.messageQueue[0][0] == a) {
            const stage = this.runtime.getTargetForStage();
            if (!stage) return true;
            const variable = stage.lookupVariableByNameAndType(b);
            if (!variable) return true;
            variable.value = this.messageQueue[0][1];
            this.messageQueue.shift();
            return true
        } else {
            return false
        }
    }
    async whenVarChange({ a }) {
        if (!this.runtime.getTargetForStage().lookupVariableByNameAndType(a)) return false;
        let b = this.runtime.getTargetForStage().lookupVariableByNameAndType(a).value;
        await new Promise(resolve => { setTimeout(resolve, 100) });
        let c = this.runtime.getTargetForStage().lookupVariableByNameAndType(a).value;
        return b != c;
    }
    async recordVar({ a, b }) {
        if (this.recording.includes(a)) return;
        const delay = async (ms) => { await new Promise(r => setTimeout(r, ms)) };
        this.recording.push(a);
        while (this.recording.includes(a)) {
            await delay(this.recordingDelay);
            let c = this.runtime.getTargetForStage().lookupVariableByNameAndType(a).value;
            let d = this.runtime.getTargetForStage().lookupVariableByNameAndType(b, 'list');
            d.value.push(c);
        }
    }
    stopRecording({ a }) {
        if (this.recording.includes(a)) {
            this.recording.splice(this.recording.indexOf(a), 1);
        }
    }
    setRecordingDelay({ a }) {
        this.recordingDelay = a;
    }
}

module.exports = OddMessage;
